import sys

class Matrix:
    def __init__(self, rows, cols):
        self.rows = rows
        self.cols = cols
        self.data = [[0] * cols for _ in range(rows)]

    def get_rows(self):
        return self.rows

    def get_cols(self):
        return self.cols

    def set_element(self, i, j, value):
        self.data[i][j] = value

    def multiply(self, other):
        if self.cols != other.rows:
            return None
        result = Matrix(self.rows, other.cols)
        for i in range(self.rows):
            for j in range(other.cols):
                sum_val = 0
                for k in range(self.cols):
                    sum_val += self.data[i][k] * other.data[k][j]
                result.data[i][j] = sum_val
        return result

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    idx = 0
    mat1_rows = int(data[idx])
    idx += 1
    mat1_cols = int(data[idx])
    idx += 1

    mat1 = Matrix(mat1_rows, mat1_cols)
    for i in range(mat1_rows):
        for j in range(mat1_cols):
            mat1.set_element(i, j, int(data[idx]))
            idx += 1

    mat2_rows = int(data[idx])
    idx += 1
    mat2_cols = int(data[idx])
    idx += 1

    mat2 = Matrix(mat2_rows, mat2_cols)
    for i in range(mat2_rows):
        for j in range(mat2_cols):
            mat2.set_element(i, j, int(data[idx]))
            idx += 1

    result = mat1.multiply(mat2)
    if result:
        output = []
        for i in range(result.rows):
            for j in range(result.cols):
                output.append(str(result.data[i][j]))
        print(' '.join(output))

if __name__ == "__main__":
    main()
